const anim_t ANIMS[ANIM_COUNT] = {
    {"away", 17, MS_AWAY, FRAMES_AWAY},
    {"alert", 8, MS_ALERT, FRAMES_ALERT},
    {"happy", 20, MS_HAPPY, FRAMES_HAPPY},
    {"typing", 12, MS_TYPING, FRAMES_TYPING},
    {"idle", 62, MS_IDLE, FRAMES_IDLE},
    {"sleep", 23, MS_SLEEP, FRAMES_SLEEP},
};

int anim_find(const char *id)
{
    for (int i = 0; id != NULL && i < ANIM_COUNT; i++) {
        if (strcmp(ANIMS[i].id, id) == 0) return i;
    }
    return -1;
}
